const KEY='form.training.v1';
// Journals saved before body scans existed pick up the imported InBody scan.
const withScans=data=>data&&typeof data==='object'&&!('scans' in data)?{...data,scans:structuredClone(scanSeed)}:data;
let state={version:1,sessions:structuredClone(seed),goals:[],scans:structuredClone(scanSeed),appliedUpdates:[...ALL_UPDATES]},storageIssue='';
try{const raw=localStorage.getItem(KEY);if(raw)state=validateBackup(withScans(JSON.parse(raw)));}catch{storageIssue='Saved data could not be read. Export any work you add before closing. The original stored data has not been overwritten.'}
// Persist a one-time data update so existing browser journals receive the new sessions.
if(!storageIssue){try{const updated=applyWorkoutUpdate(state);if(updated!==state){const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(KEY+'.before-'+LATEST_UPDATE,previous);state=updated;localStorage.setItem(KEY,JSON.stringify(state));}}catch{storageIssue='The workout update could not be saved. Export a backup before closing; existing stored data has been kept.'}}
const TABS=['dashboard','weekly','rankings','nutrition','review'],hashTab=location.hash.match(/^#insights(?:\/(\w+))?$/);
let page=hashTab?'insights':'overview',insightTab=TABS.includes(hashTab?.[1])?hashTab[1]:'dashboard',insightRange='all',dashWeek=null,radarCompare='avg',rankSort='points',openWeek=null,rankById=new Map(),week=weekStart(state.sessions.map(s=>s.date).sort().at(-1)||iso(new Date())),selected='All muscles',spotScope='all',movement='Overhead Squat',query='',scanId=null,segmentId='trunk',compareMode='previous';
const requestedDate=new URLSearchParams(location.search).get('workout');
if([...seed,...state.sessions].some(s=>s.date===requestedDate)){page='overview';week=weekStart(requestedDate);spotScope=requestedDate}
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
