const longDate=d=>day(d).toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}).toUpperCase();
const uid=()=>crypto.randomUUID();
const timed=score=>/^\d{1,2}:\d{2}$/.test(String(score).trim());
const byDate=list=>[...list].sort((a,b)=>b.date.localeCompare(a.date));
