function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function persist(){if(storageIssue){toast('Storage unavailable. Use Export backup to keep your changes.');return}try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageIssue='Browser storage is unavailable or full. Export a backup to keep your changes.';toast(storageIssue)}}
const LABELS={overview:'Overview',journal:'Logbook',progress:'Progress',insights:'Insights',body:'Body',goals:'Goals'};
const weekSessions=()=>state.sessions.filter(s=>s.date>=week&&s.date<=shift(week,6));
function heading(){const rows=weekSessions(),covered=GROUPS.filter(g=>coverage(state.sessions,week)[g]>0).length,[scan]=scansByDate(),since=scan?scanTraining(state.sessions,scan.date,null).between:0;
 return {overview:{kicker:`Week ${weekNumber(week)} · ${dateLabel(week)} – ${dateLabel(shift(week,6))}`,title:'Put in<br>the <em>work.</em>',text:rows.length?`<b>${rows.length} session${rows.length===1?'':'s'}</b> on the board this week. <b>${covered} of ${GROUPS.length}</b> muscle groups hit.`:'Nothing on the board this week yet. Log a WOD to get the clock running.'},
 journal:{kicker:`The logbook · ${state.sessions.length} sessions`,title:'Every rep<br><em>on record.</em>',text:'The weights, the wins, and everything you learned along the way.'},
 progress:{kicker:'The numbers',title:'Build the<br><em>baseline.</em>',text:'Your own baseline. Your own pace. Your next milestone.'},
 body:{kicker:`The scan log${scan?` · ${esc(scan.device||'Body scan')}`:''}`,title:'Under<br>the <em>hood.</em>',text:scan?`Latest scan ${dateLabel(scan.date)}, ${day(scan.date).getFullYear()}. <b>${since} session${since===1?'':'s'}</b> logged after that day.`:'Log a body composition scan to set your baseline.'},
 insights:{kicker:'Your training · your priorities',title:'Train for<br>your <em>goals.</em>',text:'Chest, biceps, triceps and glutes, plus fat loss. Weekly reviews, workout rankings and progress charts from your own log.'},
 goals:{kicker:'The goal board',title:'Put it on<br><em>the board.</em>',text:'Choose what matters to you. Keep it within sight.'}}[page]}
const today=()=>iso(new Date());
function insightsView(){return tabs(insightTab)+(insightTab==='weekly'?weeklyPage(state,{today:today(),openWeek}):insightTab==='rankings'?rankingsPage(state,{today:today(),sort:rankSort}):insightTab==='review'?insightsPage(state,insightRange):insightTab==='nutrition'?nutritionPage(state,{today:today()}):dashboard(state,{today:today(),weekStart:dashWeek,compare:radarCompare}))}
// window.history: 'history' in this module is the load-history helper from model.js.
function syncHash(){try{const path=new URL(location.href);path.searchParams.delete('workout');window.history.replaceState(null,'',page==='insights'?`#insights${insightTab==='dashboard'?'':'/'+insightTab}`:path.pathname+path.search)}catch{}}
function render(){rankById=new Map(analyticsFor(state,today()).stats.map(r=>[r.session.id,r]));const h=heading();
 $('#app').innerHTML=`<aside class="sidebar"><a href="#" class="brand" aria-label="FORM home"><span class="brand-symbol">${icon('kettlebell')}</span><span class="brand-word">FORM</span></a><div class="brand-sub">Training log · Est. 2026</div><nav>${Object.keys(LABELS).map(p=>`<button data-page="${p}" class="nav-item ${page===p?'active':''}" aria-label="${LABELS[p]}">${icon(p)}<span>${LABELS[p]}</span>${p==='journal'?`<small>${state.sessions.length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="tape"></div><p class="motto">Chalk up.<br>Show up.</p><div class="local-dot">Saved on this browser</div><button class="text-button" data-action="export">↓ Export backup</button><label class="text-button import-label">↑ Restore backup<input type="file" id="restore" accept="application/json,.json" hidden></label></div><div class="profile"><span class="avatar">JQ</span><div>Your training journal<small>Personal workspace</small></div></div></aside><main><header class="topbar"><span><b>The box</b><span class="crumb">/ ${LABELS[page]}</span></span><span class="private-label"><i></i>Local &amp; personal</span></header>${storageIssue?`<div class="alert">${esc(storageIssue)}</div>`:''}<div class="page-content"><div class="page-heading ${page}"><div><div class="kicker">${h.kicker}</div><h1>${h.title}</h1><p>${h.text}</p></div><div class="heading-side">${page==='overview'?clock():''}${page==='body'?'<button class="button primary cta" data-action="add-scan">＋ Log a scan</button>':'<button class="button primary cta" data-action="add">＋ Log a WOD</button>'}</div></div>${page==='overview'?overview():page==='journal'?journal():page==='progress'?progress():page==='body'?bodyPage():page==='insights'?insightsView():goals()}</div><footer><span class="footer-brand">FORM</span><span>Progress is personal.</span><div class="mobile-backup"><button class="text-button" data-mobile-export>↓ Export backup</button><button class="text-button" data-mobile-restore>↑ Restore backup</button></div><span>Local storage · Export a backup to keep your data safe</span></footer></main>`;
 bind();
}
function clock(){const last=byDate(state.sessions).find(s=>timed(s.score));return `<div class="clock"><span class="eyebrow">Last time on the clock</span>${led(last?last.score.trim():'--:--',last?'':'idle')}<small>${last?`${esc(last.title)} · ${dateLabel(last.date)}`:'No timed scores yet'}</small></div>`}
function weekControl(){return `<div class="week-control"><button data-week="-7" aria-label="Previous week">‹</button><span>${dateLabel(week)} – ${dateLabel(shift(week,6))}, ${day(week).getFullYear()}</span><button data-week="7" aria-label="Next week">›</button><button data-action="today" class="text-button">Today</button></div>`}
function overview(){const counts=coverage(state.sessions,week),rows=weekSessions(),covered=GROUPS.filter(g=>counts[g]>0).length,unknown=rows.flatMap(s=>s.movements).filter(m=>m.status==='unconfirmed'&&m.section!=='Warm-up').length,[latest,...rest]=byDate(state.sessions);
 return `<div class="section-top"><h2>The week</h2>${weekControl()}</div><div class="stats"><div class="stat"><span>Sessions logged</span><strong>${rows.length.toString().padStart(2,'0')}<small>this week</small></strong><div class="days">${Array.from({length:7},(_,i)=>`<span class="${rows.some(s=>s.date===shift(week,i))?'trained':''}" title="${dateLabel(shift(week,i))}">${'MTWTFSS'[i]}</span>`).join('')}</div></div><div class="stat"><span>Muscle groups hit</span><strong>${covered.toString().padStart(2,'0')}<small>/ ${GROUPS.length} mapped</small></strong><p>From confirmed movements only</p></div><div class="stat"><span>Still to confirm</span><strong>${unknown.toString().padStart(2,'0')}<small>movement entries</small></strong><p>Unconfirmed work stays off the map</p></div><div class="stat hazard"><div><span>House rules</span><h3>Show up.<br>Make it count.</h3></div></div></div>${scanStrip()}${weekCall()}<div class="overview-grid"><section class="card anatomy-card"><div class="card-heading"><div><div class="eyebrow">Muscle map</div><h2>What got worked</h2></div><span class="pill">This week</span></div><p class="muted">Tap a muscle to see the work behind it.</p><div class="body-stage"><div><span class="view-label">Front</span>${bodySVG('front',counts,selected)}</div><div><span class="view-label">Back</span>${bodySVG('back',counts,selected)}</div><div class="map-grid"></div></div><div class="legend"><span>Sessions</span>${['0','1','2','3+'].map((x,i)=>`<span><i class="heat-${i}"></i>${x}</span>`).join('')}</div><div class="map-disclaimer">Estimated muscle involvement, not muscle growth, training volume, or recovery. Warm-ups and unconfirmed entries are excluded. A blank region means no documented involvement.</div></section><div class="right-stack"><section class="card muscle-detail" id="muscle-spotlight">${muscleDetail(counts,rows)}</section><section class="card focus-card"><div class="eyebrow">Coverage check</div><h2>Round out the picture.</h2><p>${covered===0?'There are no confirmed movements this week yet. Log a session to start building your picture.':GROUPS.filter(g=>counts[g]===0).length?`${GROUPS.filter(g=>counts[g]===0).join(', ')} have no documented involvement this week. Check missing entries before treating these as training gaps.`:'Every mapped region has documented involvement this week. Frequency alone doesn’t tell us how much work each received.'}</p><button class="text-button" data-page="journal">Review your sessions ↗</button></section></div></div><div class="section-top"><h2>Fresh off the floor</h2><button class="text-button" data-page="journal">All sessions ↗</button></div>${latest?`<div class="recent-grid">${whiteboard(latest)}<div class="recent-side">${rest.slice(0,2).map(sessionCard).join('')}</div></div>`:'<p class="empty">No sessions yet. Start with your first workout.</p>'}`;
}
function weekCall(){const {weeks}=analyticsFor(state,today()),w=weeks.find(x=>x.start===week);if(!w)return '';const fuel=fuelFor(state,weeks,w.index);const focus=[...new Set(w.plan.items.map(i=>i.muscle))];return `<button class="week-call" data-open-week="${w.start}"><span class="eyebrow">Weekly review · ${dateLabel(w.start)} – ${dateLabel(w.end)}</span>${gradeBadge(w)}<span class="week-call-text">${focus.length?`Next week: add <b>${esc(focus.join(', '))}</b> work`:'Priority muscles covered. Hold the course'} · ${w.priority.map(p=>`${p.muscle} ${p.status==='met'?'✓':p.status==='partial'?'◐':'✕'}`).join(' · ')}${fuel?`<br><small>${esc(fuelLine(fuel))}</small>`:''}</span><span class="week-call-link">Open review ↗</span></button>`}
function scanStrip(){const [s]=scansByDate();if(!s)return `<button class="scan-strip empty" data-action="add-scan">${icon('body')}<span>No body scan yet. Log your InBody to track muscle and fat alongside your training ↗</span></button>`;const since=scanTraining(state.sessions,s.date,null).between;
 return `<button class="scan-strip" data-page="body"><span class="scan-strip-label"><span class="eyebrow">Latest body scan</span><b>${dateLabel(s.date)} · ${esc(s.device||'Scan')}</b></span>${[['Weight',s.weight,'lb'],['Skeletal muscle',s.smm,'lb'],['Body fat',s.pbf,'%'],['Lean mass',s.lbm,'lb']].map(([l,v,u])=>`<span class="readout"><strong>${fx(v)}<small>${u}</small></strong><span>${l}</span></span>`).join('')}<span class="scan-strip-go">${since} session${since===1?'':'s'} after scan day ↗</span></button>`}
function spotMoves(s,group){return s.movements.filter(m=>m.status==='confirmed'&&m.section!=='Warm-up'&&(group==='All muscles'?m.groups.length>0:m.groups.includes(group)))}
function muscleDetail(counts,rows){
 const all=byDate(state.sessions), dates=[...new Set([...all,...seed].map(s=>s.date))].sort().reverse(), source=spotScope==='all'?all:spotScope==='week'?byDate(rows):all.filter(s=>s.date===spotScope);
 const hits=source.map(s=>({s,moves:spotMoves(s,selected)})).filter(h=>h.moves.length);
 const imported=seed.find(s=>s.date===spotScope), offer=imported&&spotlightImport(all,imported);
 const period=spotScope==='all'?'across all workouts':spotScope==='week'?'in the selected week':'on '+dateLabel(spotScope);
 return `<div class="detail-top"><span class="eyebrow">Muscle spotlight</span><span class="dot-live"></span></div>
 <label class="spot-scope">Workout history<select id="spot-scope"><option value="all" ${spotScope==='all'?'selected':''}>All workouts</option><option value="week" ${spotScope==='week'?'selected':''}>Map week: ${dateLabel(week)} – ${dateLabel(shift(week,6))}</option><optgroup label="Workout date">${dates.map(d=>`<option value="${esc(d)}" ${spotScope===d?'selected':''}>${longDate(d)}, ${day(d).getFullYear()}</option>`).join('')}</optgroup></select></label>
 ${offer?.missing.length?`<div class="spot-restore"><strong>${esc(imported.title)}</strong><p>${offer.same?'Some original movements are missing from your saved workout.':'This imported workout is missing from your saved journal.'}</p><button class="button" id="spot-restore">${offer.same?'Add '+offer.missing.length+' missing movements':'Add this workout to my journal'}</button></div>`:''}
 <select class="muscle-select" aria-label="Muscle group">${['All muscles',...GROUPS].map(g=>`<option ${selected===g?'selected':''}>${g}</option>`).join('')}</select>
 <div class="involvement"><strong class="heat-text-${Math.min(hits.length,3)}">${hits.length}</strong><span>session${hits.length===1?'':'s'} ${period}<br><small>with documented involvement</small></span></div>
 ${spotScope==='week'?`<div class="mini-bars">${Array.from({length:7},(_,i)=>`<div><span class="${hits.some(({s})=>s.date===shift(week,i))?'on':''}"></span><small>${'MTWTFSS'[i]}</small></div>`).join('')}</div>`:''}
 <h4>What contributed</h4><div class="contributions">${hits.map(({s,moves})=>`<button data-edit="${esc(s.id)}"><span>${longDate(s.date)} · ${esc(s.title)}<small>${moves.map(m=>esc(m.name)+' ('+esc(m.section)+')').join(' · ')}</small></span><span>↗</span></button>`).join('')||'<p class="muted">No confirmed work for this muscle in this period.</p>'}</div>`
}
const wbNote=m=>m.result&&m.result.length<=28?m.result:m.prescription.split(/[;·]/)[0].trim();
function whiteboard(s){const parts=['Strength','Skill','WOD','Extra'].map(sec=>[sec,s.movements.filter(m=>m.section===sec)]).filter(([,ms])=>ms.length);
 return `<button class="whiteboard" data-edit="${esc(s.id)}"><span class="magnet"></span><span class="wb-date">${longDate(s.date)}</span><span class="wb-title">${esc(s.title)}</span>${parts.map(([sec,ms])=>`<span class="wb-section">${sec==='WOD'&&s.format?`WOD · ${esc(s.format.split('·')[0].trim())}`:sec}</span>${ms.map(m=>`<span class="wb-move ${m.status}">${esc(m.name)} <em>${esc(wbNote(m))}</em></span>`).join('')}`).join('')}<span class="wb-score ${String(s.score).length>12?'long':''}">Score <b>${esc(s.score||'—')}</b></span></button>`}
const kind=s=>/amrap/i.test(s.format)?'amrap':/for time/i.test(s.format)?'fortime':'other';
function sessionCard(s){const k=kind(s),moves=[...new Set(s.movements.filter(m=>m.section!=='Warm-up').map(m=>m.name))];return `<button class="session-card plate-${k}" data-edit="${esc(s.id)}"><div class="card-top"><span class="eyebrow">${longDate(s.date)}</span>${k==='other'?'':`<span class="format-badge">${k==='amrap'?'AMRAP':'For time'}</span>`}</div><h3>${esc(s.title)}</h3><p>${esc(s.format)}</p><div class="chips">${moves.slice(0,4).map(n=>`<span>${esc(n)}</span>`).join('')}${moves.length>4?`<span>+${moves.length-4}</span>`:''}</div><div class="session-bottom"><strong>${esc(s.score||'No score recorded')}</strong><span>${s.movements.length} entries ↗</span></div>${demandChip(s)}</button>`}
function demandChip(s){const r=rankById.get(s.id);if(!r)return '';return `<div class="demand-chip"><span>#${r.rank} of ${r.of} hardest · ~${Math.round(r.kcal/10)*10} kcal</span><b class="${r.ratio==null?'':r.ratio>=1.1?'up':r.ratio<=.9?'down':''}">${r.ratio==null?'Baseline':`${r.ratio>=1?'▲':'▼'} ${Math.round(Math.abs(r.ratio-1)*100)}% vs usual`}</b></div>`}
function journal(){const items=byDate(state.sessions).filter(s=>`${s.title} ${s.notes} ${s.movements.map(m=>m.name).join(' ')}`.toLowerCase().includes(query.toLowerCase()));return `<div class="section-top"><h2>${state.sessions.length} sessions on record</h2><input class="search" placeholder="Search workouts or movements…" aria-label="Search workouts" value="${esc(query)}"></div><div class="journal-grid">${items.map(sessionCard).join('')||'<div class="empty">No matching sessions.</div>'}</div><div class="note-strip">Your original notes, board prescriptions, and actual results stay separate. Open a session to review or edit it.</div>`}
function progress(){const records=byDate(state.sessions).flatMap(s=>s.movements.filter(m=>m.status==='confirmed'&&m.section!=='Warm-up').map(m=>({s,m}))),names=[...new Set(records.map(({m})=>m.name))].sort(),loadCount=new Set(records.filter(({m})=>m.load!=null).map(({m})=>m.name)).size;if(!names.includes(movement))movement=names[0]||'Overhead Squat';const entries=history(state.sessions,movement),logged=records.filter(({m})=>m.name===movement),max=entries.length?Math.max(...entries.map(e=>e.load)):0;return `<div class="progress-grid"><section class="card"><div class="section-top"><div><div class="eyebrow">Load history</div><h2>A baseline to build on</h2></div><select id="movement-select" aria-label="Movement history">${names.map(n=>`<option ${n===movement?'selected':''}>${esc(n)}</option>`).join('')}</select></div><div class="record-number">${max||'—'} <span>lb</span></div><p class="muted">Highest confirmed recorded load · not an estimated one-rep max</p><div class="load-chart">${entries.map(e=>`<div class="load-column"><strong>${e.load} lb</strong><div style="height:${Math.max(4,e.load/max*150)}px" class="${e.section==='Strength'?'strength-bar':e.section==='WOD'?'wod-bar':'extra-bar'}"></div><small>${dateLabel(e.date)}<br>${esc(e.section)}</small></div>`).join('')||'<p>No confirmed total loads yet.</p>'}</div><div class="legend chart-legend"><span><i class="strength-bar"></i>Strength</span><span><i class="wod-bar"></i>WOD</span><span><i class="extra-bar"></i>Other work</span></div><p class="map-disclaimer">Strength sets and WOD loads have different contexts. A first recorded load is a baseline, not a personal record. Per-side weights and other results without a confirmed total appear below as logged.</p><h3>Recorded results</h3>${logged.map(({s,m})=>`<button class="benchmark" data-edit="${esc(s.id)}"><div><strong>${esc(m.result||'Confirmed involvement')}</strong><small>${dateLabel(s.date)} · ${esc(s.title)} · ${esc(m.section)}</small></div><span>↗</span></button>`).join('')}${entries.flatMap(e=>e.sets.map((s,i)=>`<div class="set-history"><span>${dateLabel(e.date)} · ${esc(e.section)} · Set ${i+1}</span><strong>${s.reps} reps × ${s.load} lb</strong></div>`)).join('')}</section><section class="card"><div class="eyebrow">Benchmarks</div><h2>Keep the context.</h2><p class="muted">Compare scores only when the workout, load, and scaling match.</p>${byDate(state.sessions.filter(s=>s.score)).map(s=>`<button class="benchmark plate-${kind(s)}" data-edit="${esc(s.id)}"><div><strong>${esc(s.title)}</strong><small>${dateLabel(s.date)} · ${esc(s.format)}</small></div><span>${timed(s.score)?led(s.score.trim(),'small'):esc(s.score)}</span></button>`).join('')}</section></div><section class="card milestone-card"><div class="eyebrow">Milestones</div><h2>The beginning is a milestone, too.</h2><div class="milestone-list"><div><span class="milestone-icon plate-fortime">${String(state.sessions.length).padStart(2,'0')}</span><h3>${state.sessions.length} sessions documented</h3><p>Your training story is taking shape.</p></div><div><span class="milestone-icon plate-amrap">${String(loadCount).padStart(2,'0')}</span><h3>${loadCount} movements with a load baseline</h3><p>Confirmed total loads make future comparisons possible.</p></div><div><span class="milestone-icon plate-other">${String(state.goals.filter(g=>g.done).length).padStart(2,'0')}</span><h3>${state.goals.filter(g=>g.done).length} goals completed</h3><p>Small wins deserve a permanent place.</p></div></div></section>`}
function delta(cur,prev,k,unit,d=1){if(!prev)return '<p class="delta">Baseline scan</p>';if(cur[k]==null||prev[k]==null)return '<p class="delta">Value not recorded in one of these scans</p>';const x=Number((cur[k]-prev[k]).toFixed(d));return `<p class="delta">${x>0?'▲ +':x<0?'▼ −':'= '}${Math.abs(x).toFixed(d)} ${unit} vs ${dateLabel(prev.date)}</p>`}
