function segments(s,prev){
 const g=k=>s.segments[k]||{},name=k=>SEGMENTS.find(x=>x[0]===k)[1],bar=p=>p==null?0:Math.min(100,Math.max(0,p/150*100));
 const svg=`<svg viewBox="0 0 220 425" aria-label="Interactive segmental lean mass map"><path d="M94 29 Q110 18 126 29 Q134 41 128 55 L121 66 L121 73 L99 73 L99 66 L92 55 Q86 41 94 29Z" class="seg-head"/>${SEGMENTS.map(([k])=>`<path d="${SEG_SHAPES[k]}" class="seg ${segmentId===k?'selected':''} ${g(k).lean==null?'unmeasured':''}" data-segment="${k}" tabindex="0" role="button" aria-pressed="${segmentId===k}" aria-label="${name(k)}: ${fx(g(k).lean,2)} pounds"><title>${name(k)} · ${fx(g(k).lean,2)} lb</title></path>`).join('')}<path d="M110 86 V214 M79 112 Q110 123 141 112 M81 148 H139 M84 177 H136" class="seg-contour"/></svg>`;
 const label=(k,area)=>`<button class="seg-label ${area} ${segmentId===k?'selected':''}" data-segment="${k}" aria-pressed="${segmentId===k}"><span>${name(k)}</span><strong>${fx(g(k).lean,2)}<small>lb</small></strong><div class="pct-bar"><i style="width:${bar(g(k).pct)}%"></i><b></b></div><em>${fx(g(k).pct)}% <small>reference</small></em></button>`;
 const sym=(label,l,r)=>{const L=g(l).lean,R=g(r).lean;return L==null||R==null?'':`<div class="sym-row"><span>${label}</span><strong>${fx(L,2)} <em>L</em> · ${fx(R,2)} <em>R</em></strong><small>${lrGap(L,R).toFixed(1)}% difference</small></div>`};
 const part=g(segmentId),prior=prev?.segments[segmentId],change=part.lean!=null&&prior?.lean!=null?part.lean-prior.lean:null;
 return `<section class="card segment-card"><div class="card-heading"><div><div class="eyebrow">Segmental lean analysis</div><h2>Your body, by region</h2></div><span class="pill">5 regions</span></div><p class="muted">Select a region to explore its scan estimate.</p><div class="seg-figure">${label('leftArm','la')}${label('rightArm','ra')}<div class="seg-svg">${svg}</div>${label('leftLeg','ll')}${label('rightLeg','rl')}</div><div class="segment-insight" aria-live="polite"><div><span class="eyebrow">${name(segmentId)}</span><strong>${fx(part.lean,2)} <small>lb lean mass</small></strong></div><div><span>${change===null?'No comparison yet':`${change>0?'+':''}${change.toFixed(2)} lb`}</span><small>${change===null?'Add another measurement for this region':`vs ${dateLabel(prev.date)}, ${day(prev.date).getFullYear()}`}</small></div><p>${fx(part.pct)}% of the device reference. Lean tissue includes water and other non-fat tissue; it is not a measurement of an individual muscle.</p></div><div class="symmetry">${sym('Arms','leftArm','rightArm')}${sym('Legs','leftLeg','rightLeg')}</div><p class="map-disclaimer">Left and right refer to your body, displayed left-to-left like the scan sheet. Reference bars run from 0–150%; the tick marks 100%. Differences between sides do not measure strength. <a href="https://qr.inbody.com/ri/270/adult/en-US" target="_blank" rel="noopener noreferrer">About InBody 270 readings ↗</a></p></section>`}
// Device readings beyond the InBody sheet. Bars show each segment's fat against the device's own reference (100%).
function fatDistribution(s){const x=s.extras;if(!x)return '';const seg=x.segFat||{},rows=SEGMENTS.filter(([k])=>seg[k]&&(seg[k].fat!=null||seg[k].pct!=null)),known=rows.filter(([k])=>seg[k].fat!=null),total=known.reduce((t,[k])=>t+seg[k].fat,0),top=[...rows].sort((a,b)=>(seg[b[0]].pct??0)-(seg[a[0]].pct??0))[0];
 return `<section class="card fat-card"><div class="card-heading"><div><div class="eyebrow">Fat distribution · ${esc(s.device||'device')} readings</div><h2>Where the fat sits</h2></div><span class="pill">100% = device reference</span></div>${rows.length?`<div class="fat-rows">${rows.map(([k,l])=>{const r=seg[k],w=Math.min(100,(r.pct??0)/2);return `<div class="fat-row ${top&&top[0]===k&&(r.pct??0)>110?'top':''}"><span>${l}</span><strong>${fx(r.fat)}<small>lb</small></strong><div class="fat-bar" role="img" aria-label="${l}: ${fx(r.pct)}% of reference"><i style="width:${w}%"></i><b></b></div><em>${fx(r.pct)}%</em></div>`}).join('')}</div><p class="muted">${top&&(seg[top[0]].pct??0)>110?`${top[1]} carries ${fx(seg[top[0]].fat)} lb${total?`, ${Math.round(seg[top[0]].fat/total*100)}% of the segment fat`:''}, at ${fx(seg[top[0]].pct)}% of the device's reference. That is where a fat-loss phase should show first.`:'No segment is well above the device reference.'}</p>`:''}<div class="readings fat-readings"><div><span>Visceral fat level</span><strong>${fx(x.visceral,0)}</strong><p>Device index, not a mass. Track it on the same device.</p></div><div><span>Subcutaneous fat</span><strong>${fx(x.subFat)}<small>lb</small></strong><p>Fat under the skin, estimated by the device.</p></div><div><span>Waist-hip ratio</span><strong>${fx(x.whr,2)}</strong><p>${x.whr!=null&&x.whr>0.9?'Above the 0.90 guideline for men. ':''}Estimated by the scale, not tape-measured. Log your waist in a check-in for a real number.</p></div></div></section>`}
function composition(s){const parts=[['c-water','Total body water',s.tbw,'Water held in the body'],['c-dry','Dry lean mass',s.dlm,'Protein and minerals for muscle and bone'],['c-fat','Body fat mass',s.bfm,'Stored energy']],known=parts.every(p=>p[2]!=null),sum=known?Number((s.tbw+s.dlm+s.bfm).toFixed(1)):null,ok=known&&Math.abs(sum-s.weight)<=0.2,top=Math.max(s.smm||0,s.bfm||0,1);
 return `<section class="card comp-card"><div class="eyebrow">Body composition</div><h2>What the scale is made of</h2>${known?`<div class="comp-bar">${parts.map(([c,,v])=>`<span class="${c}" style="flex:${v}">${fx(v)}</span>`).join('')}</div>`:''}<div class="comp-legend">${parts.map(([c,l,v,d])=>`<div><i class="${c}"></i><strong>${l}</strong><small>${fx(v)} lb · ${d}</small></div>`).join('')}</div>${known?`<div class="comp-check ${ok?'':'warn'}">${fx(s.tbw)} + ${fx(s.dlm)} + ${fx(s.bfm)} = ${sum.toFixed(1)} lb ${ok?'✓ matches the scale':`· weight is ${fx(s.weight)} lb, check the sheet`}</div>`:''}${s.smm!=null&&s.bfm!=null?`<h4>Muscle vs fat</h4><div class="mf-row"><span>Skeletal muscle</span><div><i style="width:${s.smm/top*100}%"></i></div><strong>${fx(s.smm)} lb</strong></div><div class="mf-row fat"><span>Body fat</span><div><i style="width:${s.bfm/top*100}%"></i></div><strong>${fx(s.bfm)} lb</strong></div>${s.bfm>0?`<p class="muted">Skeletal muscle is ${(s.smm/s.bfm).toFixed(1)}× body fat mass on this scan.</p>`:''}`:''}</section>`}
function readings(s){return `<section class="card readings-card"><div class="eyebrow">More readings</div><h2>The fine print</h2><div class="readings"><div><span>BMI</span><strong>${fx(s.bmi)}<small>kg/m²</small></strong><p>From height and weight only. It can’t tell muscle from fat.</p></div><div><span>Basal metabolic rate</span><strong>${fx(s.bmr,0)}<small>kcal</small></strong><p>Estimated calories burned per day at rest.</p></div><div><span>SMI</span><strong>${fx(s.smi)}<small>kg/m²</small></strong><p>Arm and leg lean mass divided by height squared.</p></div><div><span>InBody’s suggested change</span><strong class="control">${signed(s.control.fat)}<small>lb fat</small> ${signed(s.control.lean)}<small>lb lean</small></strong><p>Printed by the device for its target ratio. Not a training plan.</p></div></div></section>`}
function trend(label,k,unit,asc){
 const pts=asc.filter(s=>s[k]!=null);if(pts.length<2)return `<div class="trend trend-empty"><span class="eyebrow">${label}</span><p>Two recorded values needed</p><small>Missing entries stay missing.</small></div>`;
 const t=pts.map(scanTime),v=pts.map(s=>s[k]),lo=Math.min(...v),hi=Math.max(...v),pad=Math.max((hi-lo)*.2,unit==='%'?.5:1),min=Math.max(0,lo-pad),max=hi+pad;
 const X=x=>t.at(-1)===t[0]?174:54+(x-t[0])/(t.at(-1)-t[0])*238,Y=y=>94-(y-min)/(max-min)*64,xy=t.map((x,i)=>[X(x),Y(v[i])]);
 const change=v.at(-1)-v[0];
 return `<div class="trend"><span class="eyebrow">${label}</span><div class="trend-value"><strong>${fx(v.at(-1))}<small>${unit}</small></strong><span>${change>0?'+':''}${fx(change)} ${unit==='%'?'pp':unit.trim()}<small>since first recorded value</small></span></div><svg viewBox="0 0 320 132" aria-label="${label} history"><text x="0" y="33" class="trend-date">${fx(max)}</text><text x="0" y="97" class="trend-date">${fx(min)}</text><line x1="54" x2="292" y1="30" y2="30" class="trend-axis"/><line x1="54" x2="292" y1="94" y2="94" class="trend-axis"/><polyline points="${xy.map(p=>p.map(n=>n.toFixed(1)).join(',')).join(' ')}"/>${xy.map(([x,y],i)=>`<g tabindex="0" role="button" data-select-scan="${esc(pts[i].id)}" aria-label="${esc(label)}: ${fx(v[i])}${unit}, ${esc(pts[i].date)} ${esc(pts[i].time)}"><title>${dateLabel(pts[i].date)} ${esc(pts[i].time||'time not recorded')} · ${fx(v[i])}${unit}</title><circle class="point-hit" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="12"/><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="4"/></g>`).join('')}<text x="54" y="114" class="trend-date">${dateLabel(pts[0].date)}${pts[0].date===pts.at(-1).date?` ${esc(pts[0].time)}`:''}</text><text x="292" y="130" text-anchor="end" class="trend-date">${dateLabel(pts.at(-1).date)}${pts[0].date===pts.at(-1).date?` ${esc(pts.at(-1).time)}`:''}</text></svg></div>`;
}
function bodyPage(){const scans=scansByDate();if(!scans.length)return `<section class="card baseline-note"><strong>No scans yet</strong><p>Log your InBody results to track weight, skeletal muscle, body fat, and segmental lean mass next to your training.</p><button class="button primary" data-action="add-scan">＋ Log a scan</button></section>`;
 const scan=scans.find(s=>s.id===scanId)||scans[0],i=scans.indexOf(scan),prev=compareMode==='baseline'?(i<scans.length-1?scans.at(-1):null):scans[i+1],next=scans[i-1],asc=[...scans].reverse(),training=scanTraining(state.sessions,scan.date,next?.date),since=training.between;
 const tile=(label,k,unit,extra='')=>`<div class="stat"><span>${label}</span><strong>${fx(scan[k])}<small>${unit}</small></strong>${extra}${delta(scan,prev,k,unit==='%'?'pts':unit)}</div>`;
 const meta=[longDate(scan.date),scan.time,scan.device,scan.height?`${Math.floor(scan.height/12)} ft ${Number((scan.height%12).toFixed(1))} in`:''].filter(Boolean).map(esc).join(' · ');
 return `<div class="section-top scan-top"><div><h2>${i===0?'Latest scan':'Earlier scan'}</h2><div class="scan-meta">${meta}</div></div><div class="scan-actions">${scans.length>1?`<select id="scan-select" aria-label="Choose scan">${scans.map(s=>`<option value="${esc(s.id)}" ${s===scan?'selected':''}>${dateLabel(s.date)}, ${day(s.date).getFullYear()}${s.time?` · ${esc(s.time)}`:''}</option>`).join('')}</select>`:''}<button class="text-button" data-edit-scan="${esc(scan.id)}">Review scan ↗</button></div></div>
 <div class="scan-context"><div><span class="eyebrow">${prev?'Comparison':'Starting point'}</span><p>${prev?`${dateLabel(scan.date)} against ${dateLabel(prev.date)} · ${esc(prev.device||'Device not recorded')}`:'Your first measurement is a baseline. A second scan will show changes.'}</p></div>${scans.length>1?`<label>Compare with<select id="compare-scan" aria-label="Comparison reference"><option value="previous" ${compareMode==='previous'?'selected':''}>Previous scan</option><option value="baseline" ${compareMode==='baseline'?'selected':''}>First scan</option></select></label>`:''}</div>${prev&&prev.device.trim().toLowerCase()!==scan.device.trim().toLowerCase()?'<div class="scan-notice">Different devices recorded. Read these changes with that difference in mind.</div>':''}${scanWarnings(scan).length?`<div class="scan-notice"><strong>Check these entries</strong><ul>${scanWarnings(scan).map(w=>`<li>${esc(w)}</li>`).join('')}</ul><button class="text-button" data-edit-scan="${esc(scan.id)}">Review values ↗</button></div>`:''}<div class="stats scan-stats">${tile('Weight','weight','lb')}${tile('Skeletal muscle','smm','lb')}${tile('Body fat','pbf','%',`<p class="sub">${fx(scan.bfm)} lb fat mass</p>`)}${tile('Lean body mass','lbm','lb')}</div>
 <div class="body-grid">${segments(scan,prev)}<div class="right-stack">${composition(scan)}${readings(scan)}</div></div>${fatDistribution(scan)}
 <section class="card history-card"><div class="card-heading"><div><div class="eyebrow">Scan history</div><h2>The long game</h2></div><span class="pill">${scans.length} scan${scans.length===1?'':'s'}</span></div>${scans.slice(i).length>1?`<p class="muted">History through the selected scan. Each chart has its own labeled scale; select a point to review that scan.</p><div class="trends">${trend('Weight','weight',' lb',scans.slice(i).reverse())}${trend('Skeletal muscle','smm',' lb',scans.slice(i).reverse())}${trend('Body fat','pbf','%',scans.slice(i).reverse())}</div>`:`<div class="baseline-note"><strong>Baseline set · ${dateLabel(scan.date)}</strong><p>Log your next scan to start the trend lines. Scan under similar conditions, such as the same time of day, similar hydration, and before training, so changes reflect you rather than the setup.</p></div>`}
 <div class="table-wrap"><table class="scan-table history-table"><thead><tr><th>Date</th><th>Weight</th><th>Skeletal muscle</th><th>Fat mass</th><th>Body fat</th><th>Sessions between dates</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>${asc.map((s,j)=>{const between=j?scanTraining(state.sessions,asc[j-1].date,s.date).between:null;return `<tr class="${s===scan?'current':''}"><td>${dateLabel(s.date)}, ${day(s.date).getFullYear()}</td><td>${fx(s.weight)} lb</td><td>${fx(s.smm)} lb</td><td>${fx(s.bfm)} lb</td><td>${fx(s.pbf)}%</td><td>${between===null?'Baseline':`${between} session${between===1?'':'s'}`}</td><td><button class="text-button" data-edit-scan="${esc(s.id)}" aria-label="Review scan from ${dateLabel(s.date)}">↗</button></td></tr>`}).reverse().join('')}</tbody></table></div>
 <p class="map-disclaimer">${since} session${since===1?'':'s'} on dates ${next?'strictly between this scan and the next':'after this scan day'}. ${training.boundary} session${training.boundary===1?'':'s'} on scan dates excluded because workout times are unknown. These counts do not establish what caused a scan change.</p>
 <details class="raw"><summary>Raw impedance · ${dateLabel(scan.date)}</summary><div class="table-wrap"><table class="scan-table imp-table"><thead><tr><th>Ω</th>${SITES.map(([k])=>`<th>${k.toUpperCase()}</th>`).join('')}</tr></thead><tbody>${[['khz20','20 kHz'],['khz100','100 kHz']].map(([f,l])=>`<tr><td>${l}</td>${SITES.map(([k])=>`<td>${fx(scan.impedance[f][k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">Resistance through the right arm, left arm, trunk, right leg, and left leg. InBody derives the numbers above from these; they’re kept for completeness.</p></details>${scan.notes?`<div class="note-strip">${esc(scan.notes)}</div>`:''}</section>`}
function goals(){return `<div class="goals-layout"><section class="card"><div class="eyebrow">Your next milestone</div><h2>Set an intention.</h2><form id="goal-form"><label>What would you like to achieve?<input name="title" required maxlength="200" placeholder="e.g. Complete my first full rope climb"></label><button class="button primary">＋ Add goal</button></form><div class="goal-list">${state.goals.map(g=>`<div class="goal-row ${g.done?'done':''}"><input type="checkbox" data-goal="${esc(g.id)}" ${g.done?'checked':''} aria-label="Complete ${esc(g.title)}"><span>${esc(g.title)}</span><button class="text-button" data-delete-goal="${esc(g.id)}" aria-label="Delete ${esc(g.title)}">×</button></div>`).join('')||'<p class="muted">No goals yet. Start with one that matters to you.</p>'}</div></section><div class="right-stack"><section class="whiteboard goal-board" aria-label="Goal board"><span class="magnet"></span><span class="wb-date">The goal board</span>${state.goals.map(g=>`<span class="wb-move ${g.done?'skipped':''}">${g.done?'✓':'☐'} ${esc(g.title)}</span>`).join('')||'<span class="wb-move unconfirmed">Write your first goal on the board.</span>'}</section><section class="card focus-card"><div class="eyebrow">Make it yours</div><h2>More than a heavier bar.</h2><p>A goal can be about technique, a new skill, attendance, or a repeatable benchmark. Your notes about jerk timing and half-rope climbs can be useful starting points.</p><p>Mark a goal complete when you achieve it. Goals aren’t automatically inferred from workout prescriptions.</p></section></div></div>`}
function bind(){
 if($('#insight-range'))$('#insight-range').onchange=e=>{insightRange=e.target.value;render()};
 // Nutrition settings live in the journal so they travel with backups.
 for(const [id,key] of [['#fuel-activity','activity'],['#fuel-pace','pace']])if($(id))$(id).onchange=e=>{state.nutrition={...settingsOf(state),[key]:e.target.value};persist();render()};
 document.querySelectorAll('[data-insight-tab]').forEach(b=>b.onclick=()=>{insightTab=b.dataset.insightTab;syncHash();render();window.scrollTo(0,0)});
 const pickWeek=start=>{dashWeek=start;render()};
 document.querySelectorAll('[data-dash-week]').forEach(b=>{b.onclick=()=>pickWeek(b.dataset.dashWeek);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pickWeek(b.dataset.dashWeek)}}});
 if($('#dash-week'))$('#dash-week').onchange=e=>pickWeek(e.target.value);
 document.querySelectorAll('[data-dash-step]').forEach(b=>b.onclick=()=>{const o=[...$('#dash-week').options],i=o.findIndex(x=>x.selected)+Number(b.dataset.dashStep);if(o[i])pickWeek(o[i].value)});
 if($('#radar-compare')){$('#radar-compare').value=radarCompare;$('#radar-compare').onchange=e=>{radarCompare=e.target.value;render()}}
 if($('#rank-sort'))$('#rank-sort').onchange=e=>{rankSort=e.target.value;render()};
 document.querySelectorAll('[data-open-week]').forEach(b=>{const go=()=>{page='insights';insightTab='weekly';openWeek=b.dataset.openWeek;syncHash();render();document.getElementById('week-'+openWeek)?.scrollIntoView({block:'start'})};b.onclick=go;if(b.tagName.toLowerCase()==='g')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}});
 document.querySelectorAll('[data-week-plan]').forEach(b=>b.onclick=()=>{const [start,key]=b.dataset.weekPlan.split('|'),w=analyticsFor(state,today()).weeks.find(x=>x.start===start);if(!w)return;const items=w.plan.blocks[key];openEditor(null,{date:w.plan.forWeek>today()?w.plan.forWeek:today(),title:`Accessory block ${key} · week of ${dateLabel(w.plan.forWeek)}`,format:'Accessory strength · suggested block',score:'',notes:`Suggested from the weekly review of ${dateLabel(w.start)} – ${dateLabel(w.end)}. Not completed work until you confirm it. Start with 2–3 good reps left in each set.\n${items.map(i=>`• ${i.name}: ${i.why}`).join('\n')}`,movements:items.map(i=>({...blankMovement(),name:i.name,section:'Extra',prescription:i.prescription,groups:MAP[i.name]||[]}))})});
 bindTips();
 document.querySelectorAll('[data-action="checkin"]').forEach(b=>b.onclick=()=>openCheckin());
 document.querySelectorAll('[data-edit-checkin]').forEach(b=>b.onclick=()=>openCheckin(b.dataset.editCheckin));
 document.querySelectorAll('[data-plan-block]').forEach(b=>b.onclick=()=>{const block=BLOCKS[b.dataset.planBlock];openEditor(null,{date:iso(new Date()),title:block.title,format:block.format,score:'',notes:block.notes,movements:block.moves.map(([name,prescription])=>({...blankMovement(),name,section:'Extra',prescription,groups:MAP[name]||[]}))})});
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;syncHash();render();window.scrollTo(0,0)});
 $('.brand').onclick=e=>{e.preventDefault();page='overview';render()};
 document.querySelectorAll('[data-action="add"]').forEach(b=>b.onclick=()=>openEditor());
 if($('#compare-scan'))$('#compare-scan').onchange=e=>{compareMode=e.target.value;render()};
 document.querySelectorAll('[data-segment]').forEach(b=>{const pick=()=>{segmentId=b.dataset.segment;render();document.querySelector(`.seg-label[data-segment="${segmentId}"]`)?.focus({preventScroll:true})};b.onclick=pick;if(b.tagName.toLowerCase()==='path')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick()}}});
 document.querySelectorAll('[data-select-scan]').forEach(b=>{const pick=()=>{scanId=b.dataset.selectScan;render()};b.onclick=pick;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick()}}});
 document.querySelectorAll('[data-action="add-scan"]').forEach(b=>b.onclick=()=>openScanEditor());
 document.querySelectorAll('[data-edit-scan]').forEach(b=>b.onclick=()=>openScanEditor(b.dataset.editScan));
 if($('#scan-select'))$('#scan-select').onchange=e=>{scanId=e.target.value;render()};
 document.querySelectorAll('[data-edit]').forEach(b=>{b.onclick=()=>openEditor(b.dataset.edit);if(b instanceof SVGElement)b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openEditor(b.dataset.edit)}}});
 document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{week=shift(week,Number(b.dataset.week));spotScope='week';render()});
 if($('[data-action="today"]'))$('[data-action="today"]').onclick=()=>{week=weekStart(iso(new Date()));spotScope='week';render()};
 document.querySelectorAll('[data-muscle]').forEach(b=>{const select=()=>{selected=b.dataset.muscle;render()};b.onclick=select;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});
 if($('#spot-restore'))$('#spot-restore').onclick=()=>{const original=seed.find(s=>s.date===spotScope);if(original){state.sessions=addSpotlightImport(state.sessions,original);persist();render()}};
 if($('#spot-scope'))$('#spot-scope').onchange=e=>{spotScope=e.target.value;if(spotScope!=='all'&&spotScope!=='week'){week=weekStart(spotScope);const sessions=state.sessions.filter(s=>s.date===spotScope);if(!sessions.some(s=>spotMoves(s,selected).length))selected='All muscles'}render()};
 if($('.muscle-select'))$('.muscle-select').onchange=e=>{selected=e.target.value;render()};
 if($('#movement-select'))$('#movement-select').onchange=e=>{movement=e.target.value;render()};
 if($('.search'))$('.search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('.search').focus();$('.search').setSelectionRange(pos,pos)};
 $('[data-action="export"]').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`form-backup-${iso(new Date())}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')};
 $('[data-mobile-export]').onclick=()=>$('[data-action="export"]').click();
 $('[data-mobile-restore]').onclick=()=>$('#restore').click();
 $('#restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Backup is too large (maximum 5 MB).');const imported=repairMuscleMappings(validateBackup(JSON.parse(await file.text())));imported.scans??=[];imported.appliedUpdates=[...new Set([...imported.appliedUpdates,...ALL_UPDATES])];if(!confirm(`Replace this browser’s journal with ${imported.sessions.length} sessions, ${imported.goals.length} goals, and ${imported.scans.length} body scans, plus ${(imported.checkins||[]).length} check-ins from the backup? Export your current journal first if you want to keep it.`))return;state=imported;scanId=null;storageIssue='';persist();week=weekStart(state.sessions.map(s=>s.date).sort().at(-1)||iso(new Date()));render();toast('Backup restored');}catch(err){toast(err.message||'Could not restore backup.')}};
 if($('#goal-form'))$('#goal-form').onsubmit=e=>{e.preventDefault();const title=new FormData(e.target).get('title').trim();if(!title)return;state.goals.push({id:uid(),title,done:false});persist();render()};
 document.querySelectorAll('[data-goal]').forEach(b=>b.onchange=()=>{state.goals.find(g=>g.id===b.dataset.goal).done=b.checked;persist();render()});
 document.querySelectorAll('[data-delete-goal]').forEach(b=>b.onclick=()=>{state.goals=state.goals.filter(g=>g.id!==b.dataset.deleteGoal);persist();render()});
}
// One shared tooltip for every chart mark; content is set with textContent because labels come from the journal.
function bindTips(){
 let tipEl=$('#viz-tip');if(!tipEl){tipEl=document.createElement('div');tipEl.id='viz-tip';tipEl.setAttribute('role','tooltip');document.body.append(tipEl)}
 const show=(el,x,y)=>{const [head,...rest]=el.dataset.tip.split('\n');tipEl.replaceChildren(...[head,...rest].map((t,i)=>{const d=document.createElement(i?'span':'b');d.textContent=t;return d}));tipEl.classList.add('show');const w=tipEl.offsetWidth,h=tipEl.offsetHeight;tipEl.style.left=Math.max(8,Math.min(innerWidth-w-8,x+14))+'px';tipEl.style.top=Math.max(8,y-h-12<8?y+18:y-h-12)+'px'};
 const hide=()=>tipEl.classList.remove('show');
 document.querySelectorAll('[data-tip]').forEach(el=>{el.onpointermove=ev=>show(el,ev.clientX,ev.clientY);el.onpointerleave=hide;el.onfocus=()=>{const r=el.getBoundingClientRect();show(el,r.left+r.width/2,r.top)};el.onblur=hide});
}
let editing=null;
const blankMovement=()=>({id:uid(),name:'',section:'WOD',prescription:'',result:'',status:'unconfirmed',load:null,sets:[],groups:[]});
function rowHTML(m){return `<fieldset class="movement-row" data-section="${esc(m.section)}"><div class="row-heading"><span>Movement entry</span><button type="button" class="text-button remove-movement" aria-label="Remove movement">× Remove</button></div><div class="form-grid"><label>Movement<input class="m-name" value="${esc(m.name)}" list="movement-names" required placeholder="Choose or type a movement"></label><label>Section<select class="m-section">${['Strength','WOD','Warm-up','Skill','Extra'].map(v=>`<option ${m.section===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Board prescription<input class="m-prescription" value="${esc(m.prescription)}" placeholder="e.g. 3–2–2"></label><label>Your actual result<input class="m-result" value="${esc(m.result)}" placeholder="Weight, reps, scaling, or a note"></label><label>Completion<select class="m-status"><option value="unconfirmed" ${m.status==='unconfirmed'?'selected':''}>Unconfirmed / prescribed only</option><option value="confirmed" ${m.status==='confirmed'?'selected':''}>Confirmed involvement</option><option value="skipped" ${m.status==='skipped'?'selected':''}>Skipped / substituted</option></select></label><label>Confirmed total load (lb)<input class="m-load" type="number" min="0" step="0.5" value="${m.load??''}" placeholder="Leave blank if unknown"></label></div><label>Working sets — reps @ total lb, separated by commas<input class="m-sets" value="${m.sets.map(s=>`${s.reps}@${s.load}`).join(', ')}" placeholder="e.g. 3@65, 2@85, 2@95"></label><label>Typical reps left after working sets (optional)<input class="m-rir" type="number" min="0" max="10" step="1" value="${m.rir??''}" placeholder="e.g. 2 = about two more good reps possible"></label><details><summary>Muscle mapping <span class="muted">· review or adjust</span></summary><div class="group-checkboxes">${GROUPS.map(g=>`<label><input type="checkbox" value="${g}" ${m.groups.includes(g)?'checked':''}>${g}</label>`).join('')}</div></details></fieldset>`}
function bindRow(row){row.querySelector('.remove-movement').onclick=()=>row.remove();row.querySelector('.m-section').onchange=e=>row.dataset.section=e.target.value;row.querySelector('.m-name').onchange=e=>{const key=Object.keys(MAP).find(k=>k.toLowerCase()===e.target.value.toLowerCase());if(key){e.target.value=key;row.querySelectorAll('.group-checkboxes input').forEach(c=>c.checked=MAP[key].includes(c.value))}}}
function addRow(m=blankMovement()){const wrap=document.createElement('div');wrap.innerHTML=rowHTML(m);const row=wrap.firstElementChild;$('#movement-rows').append(row);bindRow(row)}
function parsePaste(){const raw=$('#paste-input').value.trim();if(!raw){toast('Paste some notes or a table first.');return}const lines=raw.split('\n').filter(l=>l.trim());let count=0;
 const table=lines.filter(l=>l.includes('|')).map(l=>l.split('|').map(c=>c.trim().replace(/\*\*/g,'')).filter((c,i,a)=>!((i===0||i===a.length-1)&&!c)));
 const header=table.findIndex(c=>c.some(x=>/^movement$/i.test(x)));
 if(header>=0){const cols=table[header],mi=cols.findIndex(c=>/^movement$/i.test(c)),si=cols.findIndex(c=>/^section$/i.test(c)),pi=cols.findIndex(c=>/prescription/i.test(c)),ri=cols.findIndex(c=>/your numbers|actual|result/i.test(c));
 for(const cells of table.slice(header+1)){if(!cells[mi]||/^[-:]+$/.test(cells[mi])||/^(time|rounds)$/i.test(cells[mi]))continue;const name=cells[mi],key=Object.keys(MAP).find(k=>k.toLowerCase()===name.toLowerCase()||k.toLowerCase()+'s'===name.toLowerCase());addRow({...blankMovement(),name:key||name,section:/strength/i.test(cells[si]||'')?'Strength':/warm/i.test(cells[si]||'')?'Warm-up':/extra|accessory/i.test(cells[si]||'')?'Extra':/skill/i.test(cells[si]||'')?'Skill':'WOD',prescription:cells[pi]||'',result:cells[ri]==='—'?'':cells[ri]||'',groups:key?MAP[key]:[]});count++}}
 if(!count)for(const line of lines){const key=Object.keys(MAP).sort((a,b)=>b.length-a.length).find(k=>line.toLowerCase().includes(k.toLowerCase()));if(key){addRow({...blankMovement(),name:key,result:line,groups:MAP[key]});count++}}
 const notes=$('#session-notes');notes.value+=(notes.value?'\n\n':'')+'Pasted source notes:\n'+raw;
 $('#paste-input').value='';toast(count?`${count} draft entries added. Review completion, loads, and muscle mapping.`:'Notes saved in the draft. Add movements below.');
}
function openEditor(id,template){editing=id||null;const s=id?state.sessions.find(s=>s.id===id):template||{date:iso(new Date()),title:'',format:'',score:'',notes:'',movements:[]};
 $('#editor').innerHTML=`<form id="session-form"><div class="editor-heading"><div><div class="eyebrow">Your training journal</div><h2>${id?'Review session':'Log a WOD'}</h2></div><button type="button" class="close-dialog" aria-label="Close editor">×</button></div><div class="editor-content"><div class="form-grid"><label>Date<input type="date" id="session-date" required value="${s.date}"></label><label>Workout name<input id="session-title" required maxlength="120" value="${esc(s.title)}" placeholder="e.g. Quad Shredder"></label><label>Format<input id="session-format" value="${esc(s.format)}" placeholder="e.g. 9–15–21 · For time"></label><label>Score<input id="session-score" value="${esc(s.score)}" placeholder="e.g. 10:35, 3 rounds + 5 reps"></label><label>Session effort · RPE 1–10 (optional)<input id="session-rpe" type="number" min="1" max="10" step="0.5" value="${s.rpe??''}" placeholder="How hard was the whole session?"></label><label>Total minutes trained (optional)<input id="session-minutes" type="number" min="1" max="600" step="1" value="${s.minutes??''}" placeholder="Leave blank to estimate"></label></div>${id&&rankById.get(id)?`<div class="editor-report">${sessionReport(rankById.get(id),'How this session compares')}</div>`:''}<details class="paste-panel"><summary>Paste workout notes or a table</summary><p class="muted">Paste one session at a time. Table columns are extracted into draft entries; known movement names are recognized in plain notes. Review every draft before saving.</p><textarea id="paste-input" rows="4" placeholder="Paste your workout here…"></textarea><button type="button" class="button" id="parse-paste">Create draft entries</button></details><div class="section-top"><h3>What you worked on</h3><button type="button" id="add-movement" class="text-button">＋ Add movement</button></div><datalist id="movement-names">${Object.keys(MAP).map(n=>`<option value="${n}"></option>`).join('')}</datalist><div id="movement-rows"></div><div class="plate-calculator"><strong>${icon('barbell')}Barbell helper</strong><div><label>Bar (lb)<input id="bar-weight" type="number" min="0" step="0.5" value="45"></label><span>＋ 2 ×</span><label>Plates per side (lb)<input id="plate-weight" type="number" min="0" step="0.5" value="25"></label><output id="plate-total">95 lb total</output></div><small>Copy the total into the matching movement or set.</small></div><label>Session notes<textarea id="session-notes" rows="4" placeholder="Technique cues, substitutions, or how it felt…">${esc(s.notes)}</textarea></label><div id="form-error" role="alert"></div></div><div class="editor-footer">${id?'<button type="button" id="delete-session" class="text-button danger">Delete session</button>':'<span class="muted">Saved on this browser</span>'}<div><button type="button" class="button cancel-dialog">Cancel</button><button class="button primary" type="submit">Save session</button></div></div></form>`;
 s.movements.forEach(addRow);if(!id&&!template)addRow();
 const close=()=>$('#editor').close();$('.close-dialog').onclick=close;$('.cancel-dialog').onclick=close;$('#add-movement').onclick=()=>addRow();$('#parse-paste').onclick=parsePaste;
 const calc=()=>{const a=Number($('#bar-weight').value),b=Number($('#plate-weight').value);$('#plate-total').textContent=a>=0&&b>=0?`${a+2*b} lb total`:'Enter positive weights'};$('#bar-weight').oninput=calc;$('#plate-weight').oninput=calc;
 if(id)$('#delete-session').onclick=()=>{if(confirm('Delete this session from your journal?')){state.sessions=state.sessions.filter(s=>s.id!==id);persist();close();render();toast('Session deleted')}};
 $('#session-form').onsubmit=e=>{e.preventDefault();try{const movements=[...document.querySelectorAll('.movement-row')].map(row=>{const val=c=>row.querySelector(c).value.trim(),raw=val('.m-sets');const sets=raw?raw.split(',').map(t=>{const match=t.trim().match(/^(\d+)\s*@\s*(\d+(?:\.\d+)?)$/);if(!match)throw Error('Use reps@total lb for sets, for example 3@65, 2@85, 2@95.');return {reps:Number(match[1]),load:Number(match[2])}}):[];
 const load=val('.m-load')===''?(sets.length?Math.max(...sets.map(s=>s.load)):null):Number(val('.m-load'));
 return {id:uid(),name:val('.m-name'),section:val('.m-section'),prescription:val('.m-prescription'),result:val('.m-result'),status:val('.m-status'),load,sets,rir:val('.m-rir')===''?null:Number(val('.m-rir')),groups:[...row.querySelectorAll('.group-checkboxes input:checked')].map(c=>c.value)};});
 const session={id:editing||uid(),date:$('#session-date').value,title:$('#session-title').value.trim(),format:$('#session-format').value.trim(),score:$('#session-score').value.trim(),notes:$('#session-notes').value,movements};const opt=(sel,label,min,max)=>{const raw=$(sel).value.trim();if(raw==='')return null;const v=Number(raw);if(!Number.isFinite(v)||v<min||v>max)throw Error(`${label} must be between ${min} and ${max}.`);return v};session.rpe=opt('#session-rpe','Session RPE',1,10);session.minutes=opt('#session-minutes','Minutes trained',1,600);if(!session.title)throw Error('Give your workout a name.');if(movements.some(m=>!m.name))throw Error('Choose a movement name or remove its empty entry.');validateBackup({version:1,sessions:[session],goals:[]});
 if(editing)state.sessions=state.sessions.map(s=>s.id===editing?session:s);else state.sessions.push(session);persist();week=weekStart(session.date);close();render();const r=analyticsFor(state,today()).stats.find(x=>x.session.id===session.id);toast(storageIssue?'Session kept in memory. Export a backup before closing.':r?`Saved. #${r.rank} of ${r.of} hardest · ${r.verdict.toLowerCase()}${r.loads.some(l=>l.status==='best')?' · new heaviest load':''} · ~${Math.round(r.kcal/10)*10} active kcal.`:'Session saved. It’s on the board.');}catch(err){$('#form-error').textContent=err.message}};
 $('#editor').showModal();
}
function openScanEditor(id){const last=scansByDate()[0],s=id?state.scans.find(x=>x.id===id):{date:iso(new Date()),time:'',device:last?.device||'InBody 270',height:last?.height??null,notes:'',segments:{},control:{},impedance:{}};
 const v=x=>x??'',num=(attr,label,value,unit,extra='')=>`<label><span>${label}${unit?` <span class="unit">${unit}</span>`:''}</span><input type="number" step="any" ${attr} value="${v(value)}" ${extra}></label>`;
 $('#editor').innerHTML=`<form id="scan-form" class="scan-form"><div class="editor-heading"><div><div class="eyebrow">Body composition</div><h2>${id?'Review scan':'Log a scan'}</h2></div><button type="button" class="close-dialog" aria-label="Close editor">×</button></div><div class="editor-content"><div class="form-grid four"><label>Date<input type="date" id="scan-date" required value="${s.date}"></label><label>Time<input type="time" id="scan-time" value="${esc(s.time)}"></label><label>Device<input id="scan-device" maxlength="60" value="${esc(s.device)}"></label>${num('id="scan-height" min="0.1"','Height',s.height,'in')}</div>
 <fieldset><legend>Body composition</legend><div class="form-grid three">${SCAN_FIELDS.map(([k,l,u])=>num(`data-k="${k}" min="${k==='weight'?'0.1':'0'}" ${k==='pbf'?'max="100"':''}`,l,s[k],u,k==='weight'?'required':'')).join('')}</div><div id="scan-check" class="comp-check" role="status"></div></fieldset>
 <fieldset><legend>Segmental lean</legend><div class="seg-grid"><span></span><span class="unit">Lean (lb)</span><span class="unit">% reference</span>${SEGMENTS.map(([k,l])=>`<span>${l}</span><input type="number" step="any" min="0" data-seg="${k}" data-part="lean" aria-label="${l} lean mass" value="${v(s.segments[k]?.lean)}"><input type="number" step="any" min="0" data-seg="${k}" data-part="pct" aria-label="${l} reference percentage" value="${v(s.segments[k]?.pct)}">`).join('')}</div></fieldset>
 <fieldset><legend>Device’s suggested change</legend><p class="muted">Copy the sheet’s signs: a minus means lose, a plus means gain.</p><div class="form-grid">${num('data-control="fat"','Body fat mass',s.control.fat,'lb')}${num('data-control="lean"','Lean body mass',s.control.lean,'lb')}</div></fieldset>
 <fieldset><legend>Fat distribution · optional</legend><p class="muted">For devices that report it. Enter pounds; leave blank if your sheet does not show it.</p><div class="form-grid three">${num('data-extra="visceral" max="60"','Visceral fat level',s.extras?.visceral,'')}${num('data-extra="subFat"','Subcutaneous fat',s.extras?.subFat,'lb')}${num('data-extra="whr" max="3"','Waist-hip ratio',s.extras?.whr,'')}</div><div class="seg-grid"><span></span><span class="unit">Fat (lb)</span><span class="unit">% reference</span>${SEGMENTS.map(([k,l])=>`<span>${l}</span><input type="number" step="any" min="0" data-segfat="${k}" data-part="fat" aria-label="${l} fat mass" value="${v(s.extras?.segFat?.[k]?.fat)}"><input type="number" step="any" min="0" data-segfat="${k}" data-part="pct" aria-label="${l} fat reference percentage" value="${v(s.extras?.segFat?.[k]?.pct)}">`).join('')}</div></fieldset>
 <details class="paste-panel"><summary>Impedance (Ω) · optional</summary><div class="imp-grid"><span></span>${SITES.map(([k])=>`<span class="unit">${k.toUpperCase()}</span>`).join('')}${[['khz20','20 kHz'],['khz100','100 kHz']].map(([f,l])=>`<span>${l}</span>${SITES.map(([k,n])=>`<input type="number" step="any" min="0" data-imp="${f}" data-site="${k}" aria-label="${n} impedance at ${l}" value="${v(s.impedance[f]?.[k])}">`).join('')}`).join('')}</div></details>
 <label>Notes<textarea id="scan-notes" rows="3" placeholder="Conditions: time of day, hydration, before or after training…">${esc(s.notes)}</textarea></label><div id="form-error" role="alert"></div></div><div class="editor-footer">${id?'<button type="button" id="delete-scan" class="text-button danger">Delete scan</button>':'<span class="muted">Saved on this browser</span>'}<div><button type="button" class="button cancel-dialog">Cancel</button><button class="button primary" type="submit">Save scan</button></div></div></form>`;
 const close=()=>$('#editor').close();$('.close-dialog').onclick=close;$('.cancel-dialog').onclick=close;
 const check=()=>{const current=Object.fromEntries(SCAN_FIELDS.map(([k])=>{const v=$(`[data-k="${k}"]`).value.trim();return [k,v===''?null:Number(v)]})),out=$('#scan-check'),issues=scanWarnings(current);if(current.pbf>100)issues.unshift('Body fat percentage cannot exceed 100%.');if(issues.length){out.className='comp-check warn';out.textContent=issues.join(' ');return}if(['tbw','dlm','bfm','weight'].every(k=>current[k]!==null)){out.className='comp-check';out.textContent=`✓ Water + dry lean + fat = ${(current.tbw+current.dlm+current.bfm).toFixed(1)} lb, matching the weight`;}else{out.className='comp-check pending';out.textContent='Enter the values you have. Leave missing readings blank; the app checks related values without filling them in.'}};
 document.querySelectorAll('[data-k]').forEach(el=>el.oninput=check);check();
 if(id)$('#delete-scan').onclick=()=>{if(confirm('Delete this scan from your journal?')){state.scans=state.scans.filter(x=>x.id!==id);if(scanId===id)scanId=null;persist();close();render();toast('Scan deleted')}};
 $('#scan-form').onsubmit=e=>{e.preventDefault();try{const read=el=>{const x=el.value.trim();if(x==='')return null;const n=Number(x);if(!Number.isFinite(n))throw Error('Use numbers only for scan values.');return n};
 const scan={id:id||uid(),date:$('#scan-date').value,time:$('#scan-time').value,device:$('#scan-device').value.trim(),height:read($('#scan-height')),notes:$('#scan-notes').value,segments:{},control:{},impedance:{khz20:{},khz100:{}}};
 SCAN_FIELDS.forEach(([k])=>scan[k]=read($(`[data-k="${k}"]`)));SEGMENTS.forEach(([k])=>scan.segments[k]={lean:read($(`[data-seg="${k}"][data-part="lean"]`)),pct:read($(`[data-seg="${k}"][data-part="pct"]`))});['fat','lean'].forEach(k=>scan.control[k]=read($(`[data-control="${k}"]`)));['khz20','khz100'].forEach(f=>SITES.forEach(([k])=>scan.impedance[f][k]=read($(`[data-imp="${f}"][data-site="${k}"]`))));
 const extras={visceral:read($('[data-extra="visceral"]')),subFat:read($('[data-extra="subFat"]')),whr:read($('[data-extra="whr"]')),segFat:Object.fromEntries(SEGMENTS.map(([k])=>[k,{fat:read($(`[data-segfat="${k}"][data-part="fat"]`)),pct:read($(`[data-segfat="${k}"][data-part="pct"]`))}]))};
 // Only scans that report fat distribution carry the extras object.
 if([extras.visceral,extras.subFat,extras.whr,...Object.values(extras.segFat).flatMap(r=>[r.fat,r.pct])].some(x=>x!==null))scan.extras=extras;
 if(!scan.weight)throw Error('Enter the weight from the sheet.');validateBackup({version:1,sessions:[],goals:[],scans:[scan]});
 state.scans=id?state.scans.map(x=>x.id===id?scan:x):[...state.scans,scan];scanId=scan.id;persist();close();page='body';render();window.scrollTo(0,0);toast(storageIssue?'Scan kept in memory. Export a backup before closing.':'Scan saved. It’s on the board.')}catch(err){$('#form-error').textContent=err.message}};
 $('#editor').showModal();
}
